-- Estructura de las tablas que lleva la copia, sacada de information_schema
-- de producción (sólo columnas, tipos y claves primarias; sin datos).
-- Sirve para PROBAR la restauración en una base aislada. Una restauración
-- de verdad va a una base con las migraciones de supabase/ aplicadas.
CREATE TABLE public.abono_aplicaciones (id uuid DEFAULT gen_random_uuid(), abono_id uuid, invoice_id uuid, invoice_number text, amount numeric, applied_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.abonos (id uuid DEFAULT gen_random_uuid(), user_id uuid, number text, series text, client_id uuid, client_name text, client_nif text, issue_date date, total numeric, used_amount numeric, status text, devolucion_id uuid, reason text, notes text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.albaran_line_items (id uuid DEFAULT gen_random_uuid(), albaran_id uuid, product_id uuid, product_name text, product_ref text, quantity numeric, unit_price numeric, unit text, tax_rate integer, discount_percent numeric, subtotal numeric, tax_amount numeric, total numeric, sort_order integer, discount_percent_2 numeric, discount_percent_3 numeric, units_per_package numeric, cajas numeric, PRIMARY KEY (id));
CREATE TABLE public.albaranes (id uuid DEFAULT gen_random_uuid(), user_id uuid, number text, series text, client_id uuid, client_name text, client_nif text, client_address text, issue_date date, status text, subtotal numeric, total_discount numeric, total_tax numeric, total numeric, notes text, invoice_id uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), datos_extras jsonb, PRIMARY KEY (id));
CREATE TABLE public.almacenes (id uuid, user_id uuid, codigo text, nombre text, direccion text, principal boolean, activo boolean, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.apuntes_contables (id uuid DEFAULT gen_random_uuid(), user_id uuid, concepto text, plantilla text, periodicidad text, fecha date, hasta date, lineas jsonb, prestamo jsonb, creado_en timestamp with time zone DEFAULT now(), actualizado_en timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.clients (id uuid, user_id uuid, nif text, business_name text, trade_name text, email text, phone text, contact_person text, address text, city text, postal_code text, province text, country text, payment_days integer, default_payment_method text, notes text, active boolean, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), is_walk_in boolean, tarifa_id text, default_discounts numeric[], es_proveedor boolean, vendedor_id uuid, grupo_id uuid, ruta_id uuid, vat_number text, dir3 jsonb, tipo_fiscal text, codigo text, precios_especiales jsonb, descuentos_familia jsonb, PRIMARY KEY (id));
CREATE TABLE public.cobros_pagos (id uuid, user_id uuid, tipo text, series text, number text, fecha date, contraparte_id text, contraparte_nombre text, contraparte_nif text, payment_method text, cuenta_bancaria text, importe_total numeric, desglose jsonb, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.company_settings (id uuid, user_id uuid, business_name text, nif text, trade_name text, sector text, accent_theme text, email text, phone text, website text, address text, city text, postal_code text, province text, invoice_series text, next_invoice_number integer, default_payment_days integer, default_payment_method text, invoice_footer_text text, iban text, bank_name text, verifactu_enabled boolean, logo_url text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), subscription_plan text, subscription_status text, stripe_customer_id text, stripe_subscription_id text, tpv_series text, next_tpv_number integer, custom_categories jsonb, tpv_mode text, tpv_enabled boolean, igic_enabled boolean, stripe_enabled boolean, albaran_series text, next_albaran_number integer, devolucion_series text, next_devolucion_number integer, abono_series text, next_abono_number integer, plan_id text, series_documentos jsonb, tarifas jsonb, cobro_series text, next_cobro_number integer, pago_series text, next_pago_number integer, modulos jsonb, panel jsonb, comision_base text, regimen_irpf text, epigrafe_iae text, porcentaje_prorrata numeric, factura_electronica jsonb, iva_rates integer[], igic_rates integer[], PRIMARY KEY (id));
CREATE TABLE public.devolucion_line_items (id uuid DEFAULT gen_random_uuid(), devolucion_id uuid, product_id uuid, product_name text, product_ref text, quantity numeric, unit_price numeric, unit text, tax_rate integer, total numeric, restock boolean, sort_order integer, PRIMARY KEY (id));
CREATE TABLE public.devoluciones (id uuid DEFAULT gen_random_uuid(), user_id uuid, number text, series text, origin text, origin_id uuid, origin_number text, client_id uuid, client_name text, client_nif text, issue_date date, reason text, reason_note text, status text, total numeric, notes text, abono_id uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.document_templates (id uuid, user_id uuid, name text, applies_to text[], template jsonb, diagnostics jsonb, is_default boolean, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.escandallos (id uuid, user_id uuid, product_id uuid, product_ref text, product_name text, componentes jsonb, coste_adicional numeric, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.fe_comunicaciones (id uuid DEFAULT gen_random_uuid(), user_id uuid, fe_factura_id uuid, tipo text, fecha_hecho date, importe numeric, motivo text, plazo date, estado text, canal text, enviada_en timestamp with time zone, respuesta jsonb, creado_en timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.fe_facturas (id uuid DEFAULT gen_random_uuid(), user_id uuid, sentido text, invoice_id uuid, gasto_ids uuid[], formato text, numero text, fecha date, vencimiento date, nif_emisor text, nombre_emisor text, nif_receptor text, nombre_receptor text, total numeric, contenido text, huella text, canal text, estado text, estado_fecha date, motivo text, codigo text, respuesta jsonb, creado_en timestamp with time zone DEFAULT now(), actualizado_en timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.gastos (id uuid, user_id uuid, fecha date, concepto text, categoria text, proveedor_id uuid, proveedor_nombre text, base_imponible numeric, tax_rate numeric, tax_amount numeric, total numeric, payment_method text, vehiculo_id uuid, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), obra_id uuid, deducible boolean, tipo_operacion text, cuota_deducible numeric, PRIMARY KEY (id));
CREATE TABLE public.grupos_clientes (id uuid, user_id uuid, nombre text, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.historico_documentos (id uuid DEFAULT gen_random_uuid(), user_id uuid, origen text, tipo text, serie text, numero text, fecha date, codigo_tercero text, client_id uuid, base numeric, impuestos numeric, total numeric, bases jsonb, forma_pago text, observaciones text, pasa_a text[], creado_en timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.invoice_events (id bigint, user_id uuid, invoice_id uuid, invoice_number text, event_type text, severity text, detail text, old_data jsonb, new_data jsonb, db_user text, occurred_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.invoice_line_items (id uuid, invoice_id uuid, product_id uuid, product_name text, product_ref text, quantity numeric, unit_price numeric, unit text, tax_rate integer, discount_percent numeric, subtotal numeric, tax_amount numeric, total numeric, sort_order integer, cost_price numeric, discount_percent_2 numeric, discount_percent_3 numeric, units_per_package numeric, lote_id uuid, lote_codigo text, numero_serie_id uuid, numero_serie text, cajas numeric, PRIMARY KEY (id));
CREATE TABLE public.invoice_tax_breakdown (id uuid, invoice_id uuid, rate integer, base_amount numeric, tax_amount numeric, PRIMARY KEY (id));
CREATE TABLE public.invoices (id uuid, user_id uuid, number text, series text, client_id uuid, client_name text, client_nif text, client_address text, issue_date date, due_date date, paid_date date, status text, subtotal numeric, total_discount numeric, total_tax numeric, total numeric, payment_method text, notes text, verifactu_hash text, verifactu_qr_url text, verifactu_timestamp timestamp with time zone, verifactu_signature_status text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), chain_index bigint, prev_hash text, record_hash text, sealed_at timestamp with time zone, cancelled_at timestamp with time zone, cancel_reason text, rectifies_id uuid, issuer_nif text, pos_session_id uuid, number_temporary boolean, datos_extras jsonb, tipo text, sentido text, documento_origen_id uuid, documento_origen_number text, vendedor_id uuid, tarifa_id text, global_discount_percent_1 numeric, global_discount_percent_2 numeric, global_discount_percent_3 numeric, almacen_id uuid, paid_amount numeric, payment_record_ids jsonb, obra_id uuid, retencion_pct numeric, sii_status text, sii_submission_id uuid, tipo_factura_fiscal text, clave_regimen_iva text, es_intracomunitaria boolean, tipo_operacion_349 text, client_vat_number text, origen_externo text, impuesto text, PRIMARY KEY (id));
CREATE TABLE public.lotes (id uuid, user_id uuid, product_id uuid, product_ref text, product_name text, codigo text, fecha_entrada date, fecha_caducidad date, cantidad_entrada numeric, cantidad_disponible numeric, proveedor_id uuid, proveedor_nombre text, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), estado text, motivo_bloqueo text, bloqueado_en timestamp with time zone, PRIMARY KEY (id));
CREATE TABLE public.movimientos_stock (id uuid DEFAULT gen_random_uuid(), user_id uuid, product_id uuid, almacen_id uuid, origen text, documento_id uuid, cantidad numeric, precio numeric, inicial boolean, created_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.numeros_serie (id uuid, user_id uuid, product_id uuid, product_ref text, product_name text, numero_serie text, estado text, fecha_entrada date, proveedor_id uuid, proveedor_nombre text, fecha_venta date, cliente_id uuid, cliente_nombre text, invoice_id uuid, garantia_meses numeric, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.obras (id uuid, user_id uuid, numero text, nombre text, cliente_id uuid, cliente_nombre text, estado text, fecha_apertura date, fecha_cierre date, presupuesto numeric, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.ofertas (id uuid, user_id uuid, nombre text, tipo text, alcance text, alcance_ids jsonb, param_n numeric, param_m numeric, param_porcentaje numeric, param_importe numeric, tramos jsonb, regalo_product_id uuid, regalo_nombre text, regalo_cantidad numeric, desde date, hasta date, dias_semana jsonb, hora_inicio text, hora_fin text, solo_grupo_cliente_id uuid, solo_cliente_id uuid, minimo_importe numeric, minimo_unidades numeric, activa boolean, acumulable boolean, prioridad integer, usos_maximos integer, usos integer, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.ordenes_trabajo (id uuid, user_id uuid, numero text, cliente_id uuid, cliente_nombre text, descripcion text, estado text, fecha date, tecnico_id uuid, horas numeric, materiales text, obra_id uuid, invoice_id uuid, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.order_approval_items (id uuid DEFAULT gen_random_uuid(), approval_id uuid, line_item_id uuid, accepted boolean, adjusted_quantity numeric, rejection_reason text, PRIMARY KEY (id));
CREATE TABLE public.order_approvals (id uuid DEFAULT gen_random_uuid(), invoice_id uuid, token text, status text, client_message text, responded_at timestamp with time zone, expires_at timestamp with time zone, created_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.perfiles_trabajo (id uuid DEFAULT gen_random_uuid(), user_id uuid, nombre text, rol text, color text, pin_hash text, pin_sal text, activo boolean, creado_en timestamp with time zone DEFAULT now(), actualizado_en timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.pos_sessions (id uuid, user_id uuid, opened_at timestamp with time zone DEFAULT now(), closed_at timestamp with time zone, starting_cash numeric, counted_cash numeric, expected_cash numeric, cash_difference numeric, status text, notes text, created_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.products (id uuid, user_id uuid, ref text, name text, description text, category text, unit_price numeric, default_tax_rate integer, unit text, active boolean, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), barcode text, stock_quantity numeric, low_stock_threshold numeric, units_sold numeric, image text, supplier_ref text, tarifa_prices jsonb, coste_pmp numeric, coste_ultima_compra numeric, stocks_by_almacen jsonb, units_per_package numeric, purchase_price numeric, purchase_tax_rate numeric, notes text, PRIMARY KEY (id));
CREATE TABLE public.rappels (id uuid, user_id uuid, nombre text, cliente_id uuid, cliente_nombre text, tramos jsonb, activo boolean, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.recordatorios_cobro (id uuid DEFAULT gen_random_uuid(), user_id uuid, cliente_id uuid, cliente_nombre text, factura_ids uuid[], canal text, destinatario text, asunto text, importe numeric, enviado_en timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.regularizaciones_stock (id uuid, user_id uuid, fecha date, almacen_id uuid, almacen_nombre text, product_id uuid, product_name text, product_ref text, stock_teorico numeric, stock_real numeric, diferencia numeric, motivo text, notas text, created_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.rutas_reparto (id uuid, user_id uuid, nombre text, dia_semana smallint, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.traspaso_line_items (id uuid, traspaso_id uuid, product_id uuid, product_name text, product_ref text, quantity numeric, unit text, sort_order integer, PRIMARY KEY (id));
CREATE TABLE public.traspasos (id uuid, user_id uuid, number text, origen_almacen_id uuid, origen_almacen_nombre text, destino_almacen_id uuid, destino_almacen_nombre text, fecha date, notas text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.vehiculos (id uuid, user_id uuid, matricula text, nombre text, activo boolean, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.vendedores (id uuid, user_id uuid, nombre text, activo boolean, series jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), almacen_id uuid, comision_pct numeric, PRIMARY KEY (id));
CREATE TABLE public.verifactu_config (user_id uuid, activo boolean, entorno text, envio_automatico boolean, productor_nombre text, productor_nif text, nombre_sistema text, id_sistema text, version_sistema text, numero_instalacion text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), envio_bloqueado_hasta timestamptz, siguiente_envio_en timestamptz, PRIMARY KEY (user_id));
CREATE TABLE public.verifactu_registros (id uuid DEFAULT gen_random_uuid(), user_id uuid, invoice_id uuid, tipo_registro text, indice bigint, primer_registro boolean, huella text, huella_anterior text, id_emisor text, num_serie text, fecha_expedicion date, tipo_factura text, cuota_total numeric, importe_total numeric, fecha_hora_huso text, estado text, intentos integer, enviado_en timestamp with time zone, respondido_en timestamp with time zone, entorno text, csv_aeat text, codigo_error text, descripcion_error text, respuesta_cruda text, created_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
